From 3dd0dc0b0c4838499382f5820febdaae540a9501 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:49:45 +0100
Subject: [PATCH] klipper: keep the preferred format and LibreOffice's object
 descriptor

Klipper dropped LibreOffice's native formats, so a Calc entry picked
from the history pasted as a picture or not at all. Also keep the first
offered format and LibreOffice's object descriptor, which Calc needs.

BUG: 524503
---
 klipper/mimetypes.h            | 1 +
 klipper/updateclipboardjob.cpp | 9 +++++++--
 2 files changed, 8 insertions(+), 2 deletions(-)

diff --git a/klipper/mimetypes.h b/klipper/mimetypes.h
index 6993779324..22ad495221 100644
--- a/klipper/mimetypes.h
+++ b/klipper/mimetypes.h
@@ -29,6 +29,7 @@ inline constexpr auto xml = "application/xml"_L1;
 // Hints/Metadata Formats
 inline constexpr auto kdeSuggestedFileName = "application/x-kde-suggestedfilename"_L1;
 inline constexpr auto kdeForceImageCopy = "x-kde-force-image-copy"_L1;
+inline constexpr auto libreOfficeObjectDescriptor = "application/x-openoffice-objectdescriptor-xml"_L1;

 template<typename String>
 constexpr bool isImage(const String &mimetype)
diff --git a/klipper/updateclipboardjob.cpp b/klipper/updateclipboardjob.cpp
index 8deecfe676..04aea171d7 100644
--- a/klipper/updateclipboardjob.cpp
+++ b/klipper/updateclipboardjob.cpp
@@ -150,8 +150,13 @@ UpdateDatabaseJob *UpdateDatabaseJob::updateClipboard(QObject *parent,
             continue;
         }

-        // Keep the suggested file name and text formats that aren't plain text.
-        if (it != suggestedFilenameIt && !hasAcceptableTextFormatPrefix(format)) {
+        // Keep the suggested file name, text formats that aren't plain text and
+        // the source's preferred format, which is often an application's native
+        // one (e.g. LibreOffice cells) and needed to paste the entry as copied.
+        // LibreOffice also needs its object descriptor to paste its native format.
+        const bool isPreferredFormat = it == begin && !format.startsWith(MimeTypes::plainText);
+        const bool isObjectDescriptor = format.startsWith(MimeTypes::libreOfficeObjectDescriptor);
+        if (!isPreferredFormat && !isObjectDescriptor && it != suggestedFilenameIt && !hasAcceptableTextFormatPrefix(format)) {
             // Don't create un-asked for DDE links in LibreOffice apps;
             // we don't want them.
             continue;
-- 
